const processImports = async () => { if (!pendingImports.length || pendingImports.some(item => !item.bank.trim() || !item.account.trim())) { setNotice("Confirm a Bank and Account Name for every selected file."); return; } setImporting(true); try { if ((txs.length || imports.length) && !await archiveCurrentData("Replaced By New Bank Import")) return; let combined: Tx[] = [], nextImports: ImportBatch[] = [], sourceFiles: LocalSourceFile[] = [], totalRows = 0, totalAdded = 0; for (const pending of pendingImports) { const bank = pending.bank.trim(), account = pending.account.trim(), importId = `${newRuntimeId("import")}-${nextImports.length}`, sourceText = await pending.file.text(), parsed = parseCsv(sourceText, { bank, account, sourceFile: pending.file.name, importId }), existingCounts = combined.reduce((map, row) => map.set(duplicateKey(row), (map.get(duplicateKey(row)) || 0) + 1), new Map<string, number>()), incomingCounts = new Map<string, number>(), added = parsed.filter(row => { const key = duplicateKey(row), occurrence = (incomingCounts.get(key) || 0) + 1; incomingCounts.set(key, occurrence); return occurrence > (existingCounts.get(key) || 0); }); combined = [...combined, ...added]; sourceFiles.push({ id: importId, name: pending.file.name, type: pending.file.type || "text/csv", size: pending.file.size, lastModified: pending.file.lastModified, text: sourceText }); totalRows += parsed.length; totalAdded += added.length; nextImports.push({ id: importId, bank, account, sourceFile: pending.file.name, importedAt: new Date().toISOString(), rowCount: parsed.length, addedCount: added.length, fileSize: pending.file.size, lastModified: pending.file.lastModified }); } await replaceLocalSourceFiles(sourceFiles); recordAudit("Import Fresh Bank CSV Files", `Started a fresh transaction set from ${pendingImports.length} file${pendingImports.length === 1 ? "" : "s"}`); save(combined); saveImports(nextImports); const combinedDates = [...new Set(combined.map(t => t.date))].sort((a, b) => dateKey(a) - dateKey(b)), importedFrom = combinedDates[0] ? isoDate(combinedDates[0]) : "", importedTo = combinedDates.at(-1) ? isoDate(combinedDates.at(-1)!) : ""; setFromDate(importedFrom); setToDate(importedTo); setOverviewDraft(emptyOverviewFilters()); setAppliedOverviewFilters(emptyOverviewFilters()); setBankSlice("All"); setAccountSlice("All"); setDirectionSlice("All"); setCategorySlice("All"); setDetailSlice("All"); setPlaceSlice("All"); setMerchantSlice("All"); setAppliedFilters({ from: importedFrom, to: importedTo, bank: "All", account: "All", direction: "All", category: "All", detail: "All", place: "All", merchant: "All" }); setPendingImports([]); setDrafts({}); setSelectedTxIds([]); setChartSelection(null); setOverviewTransactionPage(0); setDeepDivePage(0); setWorkbenchPage(0); setNotice(`${totalAdded} original bank transactions loaded from ${pendingImports.length} file${pendingImports.length === 1 ? "" : "s"}. ${totalRows - totalAdded} overlaps within this batch were skipped. The original CSV files are saved locally. Categories start at Unclassified, local ABS place matches are applied, and merchant/category knowledge remains reviewable suggestions.`); setView("transactions"); } catch (e) { setNotice(e instanceof Error ? e.message : "Could not read the selected files"); } finally { setImporting(false); } };
