{pendingImports.length > 0 && <div className="importModalBackdrop" role="presentation"><section className="importModal" role="dialog" aria-modal="true" aria-labelledby="import-title"><div className="importModalHead"><div><span>FRESH MULTI-ACCOUNT IMPORT</span><h2 id="import-title">Confirm Each Bank And Account</h2><p>Confirm an account name for every file. Select all account files for this dataset together.</p></div><button aria-label="Close Import" onClick={() => setPendingImports([])}>×</button></div><div className="importFileList">{pendingImports.map((pending, index) => <article key={pending.id}><div className="importFileIdentity"><b>{pending.file.name}</b><small>{Math.max(1, Math.round(pending.file.size / 1024))} KB · File {index + 1} of {pendingImports.length}</small></div><label>BANK<select value={pending.bank} onChange={e => setPendingImports(items => items.map(item => item.id === pending.id ? { ...item, bank: e.target.value } : item))}><option>ANZ</option></select></label><label>ACCOUNT NAME<input autoFocus={index === 0} value={pending.account} onChange={e => setPendingImports(items => items.map(item => item.id === pending.id ? { ...item, account: e.target.value } : item))} placeholder="e.g. Everyday Account"/></label></article>)}</div><div className="importAssurance"><span>✓</span><p><b>The active transaction set starts fresh.</b> Categories begin as Unclassified. Local Australian place matches are added during import; approved merchant and category knowledge remains reviewable until you apply it.</p></div><div className="importModalActions"><button className="secondaryButton" onClick={() => setPendingImports([])}>Cancel</button><button className="import" disabled={importing || pendingImports.some(item => !item.bank.trim() || !item.account.trim())} onClick={processImports}>{importing ? "Importing Files…" : `Start Fresh With ${pendingImports.length} ${pendingImports.length === 1 ? "File" : "Files"}`}</button></div></section></div>}
